# -*- coding: utf-8 -*-
"""MANAPRINT — HOANUI · 7 boules (RANIHEI) · maquette Canva de Maeva (27/11/2026, « hoanui_canva_12_A4 »).
Reprise TELLE QUELLE : 12 billets / feuille A4 PAYSAGE (3 x 4), traits de coupe en pointillés.
Chaque billet : HOANUI, 7 BOULES, les deux mains ouvertes, les deux couronnes de fleurs, les 7 ronds
(dessins Canva posés en pochoir : en couleur, MANAPRINT les repeint, les chiffres restent noirs),
RANIHEI SISTERS & SHOP - 87 77 39 19, le N°.
RÈGLE (celle de HOANUI, inchangée — sceau Maeva 27/08), placée sur les 7 ronds de la maquette :
   haut-gauche 16-25 · haut-droite 26-45
   rangée du bas, de gauche à droite : 1-15 · 26-45 · CENTRE 46-90 · 16-25 · 1-15
   (diagonale droite 26-45 · diagonale gauche 16-25 · les deux du bord 1-15 · centre 46-90).
   Crieur : 1 à 90.
Chiffres Helvetica gras 30 pt noirs, comme sur la maquette.
Le tout est réduit pour garder 6 mm de marge d'impression (Konica / Sharp)."""

import io, random
from reportlab.pdfgen import canvas
from reportlab.lib.pagesizes import A4, landscape
from reportlab.lib import colors

try:
    from generators import canva_masque as _masque
except Exception:
    import canva_masque as _masque

PAGE_W, PAGE_H = landscape(A4)
COLS, RANGS = 3, 4
CARTES_PAGE = COLS * RANGS                # 12
CELL_W, CELL_H = 280.6299, 148.8189
NOIR = colors.black
POLICE_NUM = "Helvetica-Bold"
TAILLE_NUM = 30
# (centre x, ligne de base) : haut-gauche 16-25 · haut-droite 26-45 ·
#                              bas : 1-15 · 26-45 · centre 46-90 · 16-25 · 1-15
CASES = [(31.177, 91.559), (249.444, 91.559),
         (32.598, 29.197), (86.457, 29.197), (140.315, 29.197), (194.174, 29.197), (248.032, 29.197)]
# (x, y, largeur, hauteur, n° du dessin) : les mains, les 2 couronnes, puis les 7 ronds
_R = 52.15748
_IMGS = [(121.3735, 70.29921, 37.88293, 43.93701, 0), (73.55261, 75.11811, 27.07731, 25.51181, 1),
         (180.0, 75.11811, 27.07731, 25.51181, 1), (5.102362, 75.9685, _R, _R, 2),
         (223.3701, 75.9685, _R, _R, 2), (6.519685, 13.6063, _R, _R, 2), (60.37795, 13.6063, _R, _R, 2),
         (114.2362, 13.6063, _R, _R, 2), (168.0945, 13.6063, _R, _R, 2), (221.9528, 13.6063, _R, _R, 2)]

MARGE_SURE = 6 * 72 / 25.4
ECHELLE = min((PAGE_W - 2 * MARGE_SURE) / PAGE_W, (PAGE_H - 2 * MARGE_SURE) / PAGE_H)
DECAL_X = (PAGE_W - PAGE_W * ECHELLE) / 2.0
DECAL_Y = (PAGE_H - PAGE_H * ECHELLE) / 2.0
_DEJA = set()


def _numeros(rng):
    t = None
    for _ in range(500):
        p1 = rng.sample(range(1, 16), 2); p2 = rng.sample(range(16, 26), 2); p3 = rng.sample(range(26, 46), 2)
        t = (p2[0], p3[0], p1[0], p3[1], rng.randint(46, 90), p2[1], p1[1])
        if t not in _DEJA:
            break
    _DEJA.add(t)
    return t


def _txt(c, s, x, y, police, taille, col, centre=False):
    w = c.stringWidth(s, police, taille)
    t = c.beginText(x - w / 2.0 if centre else x, y); t.setFont(police, taille)
    t.setFillColor(col); t.textOut(s)
    c.drawText(t)


def _modele(c):
    if getattr(c, "_hoanui_modele", False):
        return
    import base64
    d = _DESSIN
    for k, v in (("{HB}", "Helvetica-Bold"), ("{H}", "Helvetica")):
        d = d.replace(k, c._doc.getInternalFontName(v))
    c.beginForm("HOANUI_CANVA", 0, 0, CELL_W, CELL_H)
    c._code.append("q\n0 g\n0 G")
    morceaux = d
    for i in range(len(_IMGS)):
        morceaux = morceaux.replace("@IMG%d@" % i, "\x00%d\x00" % i)
    for j, part in enumerate(morceaux.split("\x00")):
        if j % 2 == 1:
            i = int(part); x, y, w, h, k = _IMGS[i]
            _masque.poser(c, "HOANUI_IMG_%d" % k, base64.b64decode(_PNG[k]), x, y, w, h)
        elif part:
            c._code.append(part)
    c._code.append("Q")
    c.endForm()
    c._hoanui_modele = True


def _billet(c, ox, oy, serie, nums, col):
    _modele(c)
    c.saveState()
    c.translate(ox, oy)
    c.doForm("HOANUI_CANVA")
    _txt(c, "N\u00b0 %05d" % serie, 9.637795, 135.7795, "Helvetica-Bold", 6, colors.Color(.2, .2, .2))
    for (x, y), n in zip(CASES, nums):
        _txt(c, str(n), x, y, POLICE_NUM, TAILLE_NUM, col, centre=True)
    c.restoreState()


def generer_pdf(nb_cartes=None, nb_tickets=None, serie_start=1, theme="", couleur=True,
                nom_evenement="", titre_jeu="", couleur_perso="", date_lieu="",
                telephone="", page_start=1, evenement_id="", style="", motif="", **_ig):
    n_ = nb_cartes if nb_cartes is not None else nb_tickets
    n_ = max(1, int(n_ if n_ else CARTES_PAGE))
    buf = io.BytesIO()
    c = canvas.Canvas(buf, pagesize=(PAGE_W, PAGE_H), pageCompression=1)
    c.setTitle("HOANUI · 7 boules")
    rng = random.Random(int(serie_start) * 100003 + 2720)
    _DEJA.clear()
    serie = int(serie_start)
    faits = 0
    try:
        no_page = max(1, int(page_start))
    except Exception:
        no_page = 1
    while faits < n_:
        c.setFillColor(colors.Color(0.5, 0.5, 0.5)); c.setFont("Helvetica", 7)
        c.drawRightString(PAGE_W - DECAL_X, PAGE_H - DECAL_Y / 2.0 - 2.5, "page %d" % no_page)
        entete = "  ·  ".join(t for t in ((nom_evenement or "").strip(), (date_lieu or "").strip()) if t)
        if entete:
            c.setFillColor(NOIR); c.setFont("Helvetica-Bold", 7)
            c.drawCentredString(PAGE_W / 2.0, PAGE_H - DECAL_Y / 2.0 - 2.5, entete)
        c.saveState()
        c.translate(DECAL_X, DECAL_Y); c.scale(ECHELLE, ECHELLE)
        for idx in range(CARTES_PAGE):
            if faits >= n_:
                break
            ox = (idx % COLS) * CELL_W
            oy = (RANGS - 1 - idx // COLS) * CELL_H
            _billet(c, ox, oy, serie, _numeros(rng), NOIR)
            serie += 1
            faits += 1
        c.setStrokeColor(colors.Color(0.5, 0.5, 0.5)); c.setLineWidth(0.3); c.setDash(2, 2)
        for i in range(1, COLS):
            c.line(i * CELL_W, 0, i * CELL_W, RANGS * CELL_H)
        for j in range(1, RANGS):
            c.line(0, j * CELL_H, COLS * CELL_W, j * CELL_H)
        c.restoreState()
        c.showPage()
        no_page += 1
    c.save()
    buf.seek(0)
    return buf


_DESSIN = '.35 .35 .35 RG\n.9 w\nn\n11.33858 2.834646 m\n269.2913 2.834646 l\n273.9923 2.834646 277.7953 6.637606 277.7953 11.33858 c\n277.7953 137.4803 l\n277.7953 142.1813 273.9923 145.9843 269.2913 145.9843 c\n11.33858 145.9843 l\n6.637606 145.9843 2.834646 142.1813 2.834646 137.4803 c\n2.834646 11.33858 l\n2.834646 6.637606 6.637606 2.834646 11.33858 2.834646 c\nh\nS\n.2 .2 .2 rg\n0 0 0 rg\nBT 1 0 0 1 0 0 Tm 1.8 Tc 1 0 0 1 107.5363 127.8425 Tm /{H} 16 Tf 19.2 TL (HOANUI) Tj ET\nBT 1 0 0 1 0 0 Tm 1.3 Tc 1 0 0 1 120.2619 117.0709 Tm /{HB} 6.2 Tf 7.44 TL (7 BOULES) Tj ET\n@IMG0@\n@IMG1@\n@IMG2@\n@IMG3@\n.1 .1 .1 rg\n@IMG4@\n.1 .1 .1 rg\n@IMG5@\n.1 .1 .1 rg\n@IMG6@\n.1 .1 .1 rg\n@IMG7@\n.1 .1 .1 rg\n@IMG8@\n.1 .1 .1 rg\n@IMG9@\n.1 .1 .1 rg\n.3 .3 .3 rg\nBT 1 0 0 1 0 0 Tm .9 Tc 1 0 0 1 73.2341 7.370079 Tm /{H} 5.2 Tf 6.24 TL (RANIHEI SISTERS & SHOP  -  87 77 39 19) Tj ET'
_PNG = ['', '', '']
